files.styles.css:
/* Entry titles use 32px above and 16px below. */
/* T4 spacing: off-ramp values map to nearest 8px step (13 -> 16, 19 -> 16). */
/* T3: document boundaries share 3px solid; peer separators use 1px solid. */
/* Tokens */
:root{--type-display:clamp(48px,6vw,72px);--type-display-mobile:clamp(44px,10vw,64px);--type-collection:56px;--type-chapter:46px;--type-numeral:64px;--type-entry:34px;--type-entry-mobile:32px;--type-body:16px;--type-small:13px;--type-label:11px;--type-caption:10px;--type-mono:12px;--type-brand-mark:36px;--type-brand:15px;--type-brand-mark-mobile:30px;--type-note:28px;--type-clear:20px;--type-body-leading:1.65;--type-prose-leading:1.7;--type-list-leading:1.5;--type-entry-leading:1.15;--type-display-leading:1.02;--radius-control:6px;--layout-width:1200px;--hero-measure:510px;--hero-mobile-measure:340px;--search-width:560px;--header-height:100px;--header-mobile-height:82px;--search-height:53px;--paper:#fafaf7;--surface:#ffffff;--ink:#1a1a18;--body:#3d3d38;--line:#d9d7d0;--accent:#b3401e;--muted:#6b6b64;--prompt-background:#e9e6de;--search-border:#c9c6bf;--touch:44px;--space-1:8px;--space-2:16px;--space-3:24px;--space-4:32px;--space-5:40px;--space-6:48px;--space-8:64px;--space-10:80px;--serif:Georgia,'Times New Roman',serif;--mono:ui-monospace,SFMono-Regular,Consolas,monospace;--underline-offset:5px;--underline-thickness:2px;--leading-relaxed:1.8;--tracking-tight:-.01em;--sans:system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}

/* Entries follow their content; chapter rules organize the collection. */

/* Layout */
*{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:var(--space-3)}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);font-size:var(--type-body);line-height:var(--type-body-leading)}
a{color:inherit;text-underline-offset:var(--underline-offset)}
button,input{font:inherit}
button,a,input,summary{-webkit-tap-highlight-color:transparent}
button{cursor:pointer}
.container,.header-inner,.site-footer>div{width:min(var(--layout-width),calc(100% - calc(2 * var(--space-6))));margin-inline:auto}
.site-header{border-bottom:1px solid var(--line)}
.header-inner{min-height:var(--header-height);display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:var(--space-2)}
.brand{display:flex;align-items:center;gap:var(--space-2);text-decoration:none;font-size:var(--type-brand);font-weight:600;line-height:1.4}
.brand-mark{font:italic var(--type-brand-mark)/1 var(--serif);color:var(--ink)}
.brand-sub{display:block;font-size:var(--type-label);letter-spacing:.07em;font-weight:400;color:var(--body)}
svg{width:1.125em;height:1.125em;flex-shrink:0;vertical-align:middle}

/* Hero */
.hero{display:flex;flex-direction:column;align-items:stretch;gap:var(--space-3);padding:var(--space-6) 0 var(--space-4)}
h1{font:normal var(--type-display)/var(--type-display-leading) var(--serif);letter-spacing:var(--tracking-tight);margin:0}
h1 em{font-weight:normal;color:var(--ink)}
.hero-description{font-family:var(--serif);font-size:var(--type-body);line-height:var(--leading-relaxed);max-width:var(--hero-measure);color:var(--body);margin:0}
.hero-note{display:flex;align-items:baseline;flex-wrap:wrap;gap:calc(var(--space-3) / 2) calc(var(--space-5) / 2);padding-top:var(--space-2);border-top:1px solid var(--ink)}
.note-number{font:normal var(--type-note)/1 var(--serif);letter-spacing:-.05em}
.hero-note p{font:var(--type-brand)/1.35 var(--serif);margin:0}
.hero-note br{display:contents}
.hero-note br::after{content:" "}


/* Collection */
.collection-link{text-decoration:none;border-bottom:1px solid var(--ink);padding:var(--space-1) 0;font-size:var(--type-small);min-height:var(--touch);display:inline-flex;align-items:center;justify-content:center}
.collection-link span{margin-left:var(--space-2)}
.collection{scroll-margin-top:var(--space-4)}
#collection-title{line-height:var(--type-display-leading);font-family:var(--serif);font-size:var(--type-collection);border-bottom:3px solid var(--ink);padding-bottom:var(--space-2);max-width:100%}
.search-row{display:flex;align-items:center;justify-content:space-between;gap:var(--space-2)}
.search-box{display:flex;align-items:center;gap:var(--space-2);border:1px solid var(--search-border);border-radius:var(--radius-control);background:var(--surface);padding:0 var(--space-2);width:min(var(--search-width),100%)}
.search-box input{width:100%;height:var(--search-height);border:0;background:transparent;color:var(--ink);outline-offset:0;min-width:0}
.search-box input::placeholder{color:var(--muted)}
.snapshot{font-size:var(--type-label);color:var(--muted);letter-spacing:.025em}
.filter-row{display:flex;align-items:center;justify-content:space-between;gap:var(--space-2);margin:var(--space-3) 0 var(--space-3)}
.filter{border:0;border-radius:0;padding:var(--space-1) var(--space-2);background:none;color:var(--body);font-size:var(--type-mono);min-height:var(--touch);display:inline-flex;align-items:center;justify-content:center}
.filter:hover{color:var(--ink);text-decoration:underline;text-decoration-color:var(--ink);text-underline-offset:var(--underline-offset)}
.filter:disabled{cursor:default;color:var(--muted)}
.filter:disabled:hover{text-decoration:none}
.filter.active{color:var(--ink);text-decoration:underline;text-decoration-color:var(--accent);text-decoration-thickness:var(--underline-thickness);text-underline-offset:var(--underline-offset)}
#results-count{font-size:var(--type-label);color:var(--muted);white-space:nowrap;margin:0}
.search-box input::-webkit-search-cancel-button{-webkit-appearance:none}
#clear-search{min-width:var(--touch);min-height:var(--touch);display:inline-flex;align-items:center;justify-content:center;border:0;background:transparent;color:var(--ink);padding:var(--space-1);font-size:var(--type-clear);flex-shrink:0}
.filter-controls,.filters{display:flex;flex-wrap:wrap;gap:var(--space-1)}

/* Chapters and entries */
.chapter{margin-top:0}
/* A lone filtered chapter starts directly below the controls. */
.collection:has(> .chapter:not([hidden]) ~ .chapter:not([hidden])) > .chapter:not([hidden]){margin-top:var(--space-10)}
.chapter-heading{line-height:var(--type-entry-leading);display:flex;flex-wrap:wrap;align-items:baseline;gap:var(--space-1) var(--space-2);border-bottom:3px solid var(--ink);padding-bottom:var(--space-2);margin:0 0 var(--space-4);font-size:var(--type-chapter)}
.chapter-heading::before{font:normal var(--type-numeral)/1 var(--serif);color:var(--ink)}
.chapter-heading span{font:var(--type-small) var(--sans);letter-spacing:0;color:var(--muted)}
.skill-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--space-3);align-items:start}
/* Reserve two rule pixels; the resting rule uses only the upper pixel. */
.skill-card{padding:var(--space-4) var(--space-4) 0;border-top:2px solid transparent;position:relative}
.skill-card::before{content:"";position:absolute;top:-2px;left:0;right:0;border-top:1px solid var(--ink)}
.skill-grid > .skill-card:first-child::before{border-top:0}
.skill-card:hover,.skill-card:focus-within{border-top-color:var(--ink)}
.card-meta{display:flex;flex-wrap:wrap;align-items:center;gap:var(--space-1);font-size:var(--type-label);color:var(--muted);white-space:normal}
.number{font:var(--type-mono) var(--mono);color:var(--muted);margin-right:var(--space-1)}
.category{font-weight:600;color:var(--ink);font-size:var(--type-mono);font-variant-caps:small-caps;letter-spacing:.08em;flex-shrink:0}
.dot{color:var(--muted)}
h2,.skill-card h3{font:normal var(--type-entry)/var(--type-entry-leading) var(--serif);letter-spacing:0;margin:var(--space-3) 0 var(--space-2);overflow-wrap:anywhere}
.description{font-family:var(--serif);color:var(--body);margin:0;font-size:var(--type-body);line-height:var(--type-prose-leading)}
.fit{margin:var(--space-3) 0}
.fit p{margin:0;font-size:var(--type-small);line-height:var(--type-prose-leading);color:var(--body)}
.fit strong{font-weight:600;color:var(--ink)}
.inside-list{margin:var(--space-1) 0 var(--space-3);padding:0;list-style:none}
.inside-list li{margin:var(--space-1) 0;font-size:var(--type-small);line-height:var(--type-list-leading);color:var(--body)}
.inside-name{font-family:var(--mono);font-size:var(--type-mono);color:var(--ink);overflow-wrap:anywhere}
.inside-note{margin:0 0 var(--space-3);font-size:var(--type-label);color:var(--muted)}
.inside-kind{font-size:var(--type-label);color:var(--muted)}
details{border-top:1px solid var(--line)}
summary{display:flex;justify-content:space-between;align-items:center;list-style:none;padding:var(--space-2) 0;font-size:var(--type-mono);font-weight:500;cursor:pointer}
summary:hover{text-decoration:underline}
summary::-webkit-details-marker{display:none}
summary svg{width:1em;transition:transform .2s}
details[open] summary svg{transform:rotate(180deg)}
.card-footer{border-top:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;gap:var(--space-1);min-height:calc(var(--space-5) + var(--space-2));font-size:var(--type-label);flex-wrap:wrap}
.card-footer a{min-height:var(--touch);display:flex;gap:var(--space-1);align-items:center;text-decoration:none}
.card-footer a:visited{color:var(--muted)}
.card-footer a:hover{text-decoration:underline}
.card-footer a svg{width:.875em}
.meta-stars{font:var(--type-mono) var(--mono);display:flex;align-items:center;gap:var(--space-1);font-variant-numeric:tabular-nums;color:var(--ink);white-space:nowrap}
.meta-stars svg{width:.875em;height:.875em;color:var(--ink)}

/* Footer */
.site-footer>div{display:flex;align-items:center;justify-content:space-between;gap:var(--space-3);padding:var(--space-3) 0 var(--space-4);font-size:var(--type-label)}
.site-footer>div>span{font-weight:600}
.site-footer p{font-size:var(--type-label);color:var(--muted)}
.site-footer a{text-decoration:none;white-space:nowrap;min-height:var(--touch);display:inline-flex;align-items:center;justify-content:center}

/* States */
button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible{outline:2px solid var(--accent);outline-offset:var(--underline-offset)}
#empty-state{text-align:center;padding:var(--space-8) var(--space-2);border:1px solid var(--line);border-radius:var(--radius-control)}
#empty-state p{color:var(--body)}
#reset-filters{padding:var(--space-1) var(--space-2);border:0;border-radius:var(--radius-control);background:var(--ink);color:var(--paper);font-size:var(--type-mono);min-height:var(--touch);display:inline-flex;align-items:center;justify-content:center}
.sr-only,.skip-link:not(:focus){position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.skip-link:focus{position:fixed;top:var(--space-1);left:var(--space-1);padding:var(--space-1);background:var(--ink);color:var(--paper);z-index:10}
[hidden]{display:none!important}
.noscript{padding:var(--space-2);color:var(--body)}

/* Media queries */
@media(min-width:641px){
  .skill-grid > .skill-card.first-visible::before{border-top:0}
  .skill-grid > .skill-card:nth-child(2)::before{border-top:0}
  .skill-grid:has(> article:only-child) > article{grid-column:1 / -1}
  .skill-grid:has(> article:only-child) :is(.description,.fit p,.top-inside){max-width:62ch}
  .skill-grid:has(> article:not([hidden])):not(:has(> article:not([hidden]) ~ article:not([hidden]))) > article{grid-column:1 / -1}
  .skill-grid:has(> article:not([hidden])):not(:has(> article:not([hidden]) ~ article:not([hidden]))) :is(.description,.fit p,.top-inside){max-width:62ch}
}



@media(max-width:1000px){
  .container,.header-inner,.site-footer>div{width:calc(100% - calc(var(--space-5) + var(--space-2)))}
  .filter-row{align-items:start;flex-direction:column;gap:var(--space-2)}
  .skill-card{padding:var(--space-3) var(--space-3) 0}
  .site-footer>div{flex-wrap:wrap}
  .site-footer p{order:3;width:100%;margin:0}
}
@media(min-width:1000px){
  /* The numeral consumes zero row width, hanging inside the 32px inset. */
  .skill-card{padding:var(--space-4) var(--space-4) 0}
}
@media(max-width:640px){
  .skill-card.first-visible::before{border-top:0}
  .container,.header-inner,.site-footer>div{width:calc(100% - calc(var(--space-4) + var(--space-1) / 2))}
  .header-inner{min-height:var(--header-mobile-height)}
  .brand-mark{font-size:var(--type-brand-mark-mobile)}
  .brand{gap:var(--space-1);font-size:var(--type-small)}
  .brand-sub{font-size:var(--type-caption)}
  .collection-link{font-size:var(--type-label)}
  .collection-link span{margin-left:var(--space-1)}
  .hero{padding:var(--space-3) 0;gap:var(--space-2)}
  h1{font-size:var(--type-display-mobile);letter-spacing:var(--tracking-tight)}
  .hero-description{font-size:var(--type-body);max-width:var(--hero-mobile-measure)}
  .hero-note{gap:calc(var(--space-3) / 4) calc(var(--space-5) / 4);padding-top:calc(var(--space-3) / 2)}
  .note-number{font-size:var(--type-brand);letter-spacing:0}
  .hero-note p{font-size:var(--type-mono);margin:0}

  .search-row{display:block}
  .search-box{width:100%}
  .snapshot{margin:var(--space-1) 0 0}
  .filter-row{margin:var(--space-2) 0}
  .filter{padding:var(--space-1) var(--space-1);font-size:var(--type-label)}
  .skill-grid{grid-template-columns:1fr;gap:var(--space-2)}
  h2,.skill-card h3{font-size:var(--type-entry-mobile)}

  .site-footer>div{padding:var(--space-3) 0;gap:var(--space-2)}
  .site-footer p{line-height:var(--leading-relaxed)}
  summary{min-height:var(--space-6)}
  .filter-controls,.filters{gap:var(--space-1)}
}
@media(prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*:before,*:after{transition:none!important}
}


#chapter-workflow::before{content:"I" / ""}
#chapter-quality::before{content:"II" / ""}
#chapter-design::before{content:"III" / ""}
#chapter-efficiency::before{content:"IV" / ""}
#chapter-knowledge::before{content:"V" / ""}
#chapter-discovery::before{content:"VI" / ""}

.skill-card h3{margin:var(--space-4) 0 var(--space-2)}
.top-inside{margin:var(--space-2) 0 var(--space-1);font-size:var(--type-small);line-height:var(--type-list-leading);color:var(--body)}
.top-inside-label{font-size:var(--type-label);color:var(--muted)}
.chapter-lede{font-size:var(--type-small);color:var(--body);margin:0 0 var(--space-4)}
.skill-grid :is(.inside-list li,.inside-note){max-width:62ch}
mark{font-weight:600;text-decoration:underline;text-decoration-color:var(--accent);text-decoration-thickness:var(--underline-thickness);text-underline-offset:var(--underline-offset);background:var(--prompt-background);color:var(--ink)}
.example-prompt{margin:var(--space-1) 0 0;padding:var(--space-1) var(--space-2);border-left:1px solid var(--line);background:var(--prompt-background);color:var(--body);font-family:var(--mono);font-size:var(--type-mono);line-height:var(--type-list-leading);overflow-wrap:anywhere}
.item-category{font-family:var(--mono);font-size:var(--type-mono);color:var(--muted)}
.favourite-button{padding:0;min-height:var(--touch);border:0;background:none;color:var(--muted)}
.favourite-button[aria-pressed="true"]{color:var(--ink)}
.item-favourite-button{display:inline-flex;align-items:center;justify-content:center;min-height:24px;min-width:24px;padding:0 var(--space-1);border:0;background:none;font-family:var(--mono);font-size:var(--type-mono);color:var(--muted)}
.item-favourite-button[aria-pressed="true"]{color:var(--ink)}

.favourite-button:hover,.item-favourite-button:hover{color:var(--ink)}

.start-strip,.how-to{margin:0 0 var(--space-5)}
.start-strip{border-top:1px solid var(--ink);padding-top:var(--space-2)}
.start-strip h2,.how-to h2{font:normal var(--type-note)/var(--type-entry-leading) var(--serif);letter-spacing:0;margin:0 0 var(--space-1)}
.start-criterion{margin:0 0 var(--space-3);font-size:var(--type-small);line-height:var(--type-prose-leading);color:var(--body)}
.start-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--space-3)}
.start-item{display:flex;flex-direction:column;gap:var(--space-1);padding-top:var(--space-2);border-top:1px solid var(--line)}
.start-phase{font-family:var(--mono);font-size:var(--type-mono);font-weight:600;font-variant-caps:small-caps;letter-spacing:.08em;color:var(--ink)}
.start-item a{font:normal var(--type-note)/var(--type-entry-leading) var(--serif);color:var(--ink);text-underline-offset:var(--underline-offset);overflow-wrap:anywhere}
.start-when{font-size:var(--type-small);line-height:var(--type-prose-leading);color:var(--body)}
.start-stars{font:var(--type-mono) var(--mono);font-variant-numeric:tabular-nums;color:var(--muted)}
.how-to{border-top:1px solid var(--line);padding-top:var(--space-2);max-width:62ch}
.how-to p{margin:0 0 var(--space-1);font-size:var(--type-small);line-height:var(--type-prose-leading);color:var(--body)}
.card-use{flex:0 0 100%;margin:0;padding:var(--space-1) 0 0;font:var(--type-mono)/var(--type-list-leading) var(--mono);color:var(--muted);overflow-wrap:anywhere}
.card-use-label{color:var(--ink)}
.card-use-code{font:inherit;color:var(--ink)}
@media(max-width:1000px){.start-list{grid-template-columns:1fr}}
.reveal-note{margin:0;font-size:var(--type-small);color:var(--muted)}
.reveal-note:not(:empty){margin:var(--space-2) 0 0}
.skill-card h3:focus-visible{outline:2px solid var(--ink);outline-offset:var(--underline-offset)}

